const FE_LABELS = ["fe", "frontend"];
const FE_COMPONENT_NAMES = ["fe"];
const LOC_LABELS = ["localization", "needs_localization"];
const MAX_AGE_DAYS = 14;
const MEMORY_LIMIT = 2000;
const store = $getWorkflowStaticData("global");
if (!Array.isArray(store.postedIssueKeys)) { store.postedIssueKeys = []; }
const results = [];
for (const item of $input.all()) {
  const raw = item.json.body || item.json;
  const issue = raw.issue || (raw.key ? raw : {});
  const fields = issue.fields || {};
  const key = issue.key;
  if (!key) { continue; }
  const labels = Array.isArray(fields.labels) ? fields.labels : [];
  const components = Array.isArray(fields.components) ? fields.components : [];
  const hitFeLabels = labels.filter(function (l) { return FE_LABELS.indexOf(String(l).toLowerCase()) !== -1; });
  const hitFeComponents = components.filter(function (c) { return FE_COMPONENT_NAMES.indexOf(String((c && c.name) || "").toLowerCase()) !== -1; }).map(function (c) { return c.name + " (component)"; });
  const hitLocLabels = labels.filter(function (l) { return LOC_LABELS.indexOf(String(l).toLowerCase()) !== -1; });
  const isFe = hitFeLabels.length > 0 || hitFeComponents.length > 0;
  const isLoc = hitLocLabels.length > 0;
  if (!isFe && !isLoc) { continue; }
  const createdMs = fields.created ? Date.parse(fields.created) : 0;
  if (createdMs && (Date.now() - createdMs) / 86400000 > MAX_AGE_DAYS) { continue; }
  if (store.postedIssueKeys.indexOf(key) !== -1) { continue; }
  store.postedIssueKeys.push(key);
  if (store.postedIssueKeys.length > MEMORY_LIMIT) { store.postedIssueKeys = store.postedIssueKeys.slice(-MEMORY_LIMIT); }
  const url = "https://futuremedia.atlassian.net/browse/" + key;
  const project = (fields.project && (fields.project.name || fields.project.key)) || "unknown project";
  const summary = fields.summary || "(no summary)";
  const issueType = (fields.issuetype && fields.issuetype.name) || "Issue";
  const priority = (fields.priority && fields.priority.name) || "No priority";
  const status = (fields.status && fields.status.name) || "unknown status";
  const reporter = (fields.reporter && fields.reporter.displayName) || "unknown";
  const assignee = (fields.assignee && fields.assignee.displayName) || "unassigned";
  const matched = hitFeLabels.concat(hitFeComponents).concat(hitLocLabels).join(", ");
  const headline = isFe ? ":mag: *FE ticket*" : ":globe_with_meridians: *Localization ticket*";
  const text = headline + " \u00b7 <" + url + "|" + key + "> \u00b7 " + project + "\n"
    + "*" + summary + "*\n"
    + issueType + " \u00b7 " + priority + " \u00b7 " + status + " \u00b7 matched: " + matched + "\n"
    + "Reporter: " + reporter + " \u00b7 Assignee: " + assignee;
  results.push({ json: { issueKey: key, issueUrl: url, project: project, summary: summary, matched: matched, category: isFe ? "FE" : "Localization", slackText: text } });
}
return results;

